WITH unpacked AS (SELECT id, customer_id, created_at, coupon_codes, items, ship_to, attributes, ship_to.city AS ship_city, COALESCE(ship_to.zip, 'UNKNOWN') AS zip_or_unknown, COALESCE(attributes['utm_source'], 'none') AS utm_source_or_default, ARRAY_JOIN(ARRAY_SORT(coupon_codes), ',') AS coupons_text FROM carts WHERE customer_id IN (5, 17, 19)) SELECT ship_city, customer_id, COUNT(CASE WHEN ship_city = 'London' THEN 1 END) AS london_count, COUNT(CASE WHEN ship_city = 'Singapore' THEN 1 END) AS singapore_count, COUNT(DISTINCT utm_source_or_default) AS distinct_utm_source_or_defaults, GROUPING(ship_city) AS grouping_level FROM unpacked GROUP BY ROLLUP (ship_city, customer_id) ORDER BY ship_city DESC NULLS LAST;
